O4 = "EPJA-MATE-NB2-OAD-04"

# ============================================================ OAD-04 clase 1
F = ("Ficha 1 (datos inventados). Problema: un rollo de cable mide 12 m. Se usan 3/4 del rollo en un taller y 1,5 m en un pasillo. "
     "El rollo costó $24.000. Pregunta: ¿cuántos metros de cable quedan?")
C(O4, 1, F,
  "Hoy aprenderé a leer un problema, separar los datos que sirven de los que sobran y decidir qué operaciones necesito antes de calcular.",
  ["Un problema bien resuelto empieza antes de calcular: se lee, se entiende qué se pregunta y se separan los datos. Tú ya lo haces al revisar una cuenta: miras qué te piden y qué números importan. Hoy lo ordenamos por escrito.",
   "Primero subraya la pregunta: «¿cuántos metros quedan?». Después marca los datos que sirven: 12 m, 3/4 del rollo y 1,5 m. Un dato como el precio puede sobrar; no todos los datos se usan. Por último, elige las operaciones: 3/4 del rollo es multiplicar, y lo usado se resta del total.",
   "Escribe la cuenta antes de resolver: 12 − 3/4 × 12 − 1,5. Palabras como «de» piden multiplicar; «cuántas veces cabe», dividir; «en total», sumar; «queda», restar. Al final, responde la pregunta con una frase y la unidad."],
  [("dato", "número o información que entrega el problema"), ("pregunta", "lo que el problema pide encontrar"), ("estrategia", "plan de qué operaciones usar y en qué orden"), ("dato que sobra", "información que no se necesita para responder")],
  [("Separar datos útiles y datos que sobran", "Una bodega tiene 20 cajas; se despachan 3/5 de ellas; cada caja pesa 12 kg. ¿Cuántas cajas se despachan?", ["La pregunta es cuántas cajas, no cuántos kilos: el peso sobra.", "3/5 de 20: 20 ÷ 5 = 4 y 4 × 3 = 12."], "12 cajas"),
   ("Escribir la cuenta", "Un tambor de 8 litros usa 1/4 de su contenido. ¿Cuántos litros quedan?", ["Lo usado es 1/4 de 8: 8 ÷ 4 = 2.", "Queda lo que no se usó: 8 − 2 = 6."], "6 litros")],
  [("Usar todos los datos aunque sobren.", "Se cree que cada número del problema debe entrar en la cuenta.", "Primero identifica la pregunta; usa solo los datos que ayudan a responderla."),
   ("Restar 3/4 directamente de 12, sin calcular 3/4 de 12.", "Se confunde la fracción con una cantidad de metros.", "3/4 es una parte del rollo: primero se calcula 3/4 de 12 = 9 m.")],
  [Q("{F} ¿Qué pregunta responde el problema?", "cuántos metros de cable quedan", "cuánto costó el rollo", "cuánto mide el taller", "La última oración del problema indica lo que se debe encontrar."),
   Q("{F} ¿Qué dato no se necesita para responder?", "el precio $24.000", "los 12 m", "los 1,5 m", "El precio no sirve para saber cuántos metros quedan."),
   Q("{F} ¿Cuántos metros se usaron en el taller?", "9", "3", "0,75", "3/4 de 12 es 12 ÷ 4 = 3 y 3 × 3 = 9."),
   Q("{F} ¿Cuántos metros se usaron en total entre taller y pasillo?", "10,5", "9", "4,5", "Se suman 9 m del taller y 1,5 m del pasillo."),
   Q("{F} ¿Cuántos metros de cable quedan?", "1,5", "10,5", "2,25", "Se restan los 10,5 m usados al total de 12 m."),
   Q("{F} ¿Qué cuenta resuelve el problema?", "12 − 3/4 × 12 − 1,5", "12 − 3/4 − 1,5", "12 + 9 + 1,5", "Primero se calcula 3/4 de 12 y luego se restan lo usado en taller y pasillo."),
   Q("Un frasco de 2,5 litros usa 3/5 de su contenido y costó $3.000. ¿Cuántos litros quedan?", "1 litro", "1,9 litros", "1,5 litros", "3/5 de 2,5 es 1,5 y 2,5 − 1,5 = 1; el precio sobra."),
   Q("Una receta para 4 personas usa 3/4 kg de harina. ¿Cuánta harina hace falta para 8 personas?", "1 1/2 kg", "3 kg", "7/8 kg", "8 personas es el doble de 4, y el doble de 3/4 es 6/4, o sea 1 1/2."),
   Q("La expresión «la mitad de 3/4» se calcula con", "1/2 × 3/4", "1/2 + 3/4", "3/4 − 1/2", "La palabra «de» entre fracciones pide multiplicar."),
   T2("En un problema, ¿se deben usar siempre todos los datos?", "No: pueden sobrar datos que no ayudan a responder", "Sí: todos los datos cuentan", "Algunos datos pueden ser informativos y no se usan para la pregunta."),
   Q("Si el problema pregunta «cuántas veces cabe» una medida en otra, la operación probable es", "dividir", "sumar", "restar", "Ver cuántas veces cabe una cantidad en otra se responde dividiendo."),
   Q("Una cinta de 18 m se corta en trozos de 0,75 m. ¿Cuántos trozos salen?", "24", "13,5", "17,25", "18 ÷ 0,75 equivale a 1.800 ÷ 75 = 24."),
   Q("Se compran 2,5 kg de una fruta a $1.600 el kilo (dinero de ejemplo). ¿Cuánto cuestan?", "$4.000", "$1.600", "$3.200", "2,5 × 1.600 es 3.200 más la mitad de 1.600, o sea 4.000.")],
  Q("En una feria de ejemplo hay 40 cajas, se venden 3/5 y se regalan 4. Cada caja cuesta $2.500. ¿Cuántas cajas quedan?", "12", "36", "20", "3/5 de 40 son 24 y 40 − 24 − 4 = 12; el precio sobra."),
  [("¿Qué debes marcar primero en un problema?", "La pregunta", "Saber qué se pide orienta la elección de los datos y las operaciones."),
   ("En Matemática: ¿qué es un dato que sobra?", "Información que no se necesita para responder", "Puede aparecer en el texto, pero no entra en la cuenta."),
   ("¿Cuánto es 1/2 de 3/4?", "3/8", "Se multiplican 1 × 3 = 3 arriba y 2 × 4 = 8 abajo, y queda 3/8.")],
  ("Con el problema del cable de la ficha 1 o con otro que inventes, escribe: la pregunta, los datos que sirven, el dato que sobra, la cuenta y la respuesta con una frase. Explícalo a otra persona.",
   "Pregunta: cuántos metros quedan. Datos: 12 m, 3/4 y 1,5 m. Sobra el precio. Cuenta: 12 − 9 − 1,5 = 1,5. Quedan 1,5 m de cable.",
   ["identifica la pregunta", "separa datos útiles y sobrantes", "escribe cuenta y respuesta con unidad"],
   ["lista de datos y pregunta", "cuenta y frase de respuesta"],
   ["usar el dato que sobra", "no escribir la respuesta con unidad"],
   "Si usa el precio, pide que lea la pregunta otra vez y diga si el precio ayuda a responderla."),
  "Escribe pregunta, datos y cuenta: una caja de 24 kg se vende en 3/8 por la mañana y 4,5 kg por la tarde.",
  "Inventa un problema con un dato que sobra y pídele a otra persona que lo encuentre.")

# ============================================================ OAD-04 clase 2
F = ("Ficha 2 (datos inventados). Cuentas: (1) 2,5 + 3 × 0,5; (2) (1/2 + 1/4) × 8; (3) 10 − 4 ÷ 0,5; (4) 1/2 × 6 + 0,75. "
     "Regla: primero los paréntesis, luego multiplicaciones y divisiones de izquierda a derecha, y al final sumas y restas.")
C(O4, 2, F,
  "Hoy aprenderé el orden en que se hacen las operaciones cuando una cuenta mezcla sumas, restas, multiplicaciones, divisiones, fracciones y decimales.",
  ["Una cuenta combinada tiene varias operaciones juntas. Si cada persona las hiciera en otro orden, saldrían resultados distintos. Por eso hay un orden acordado, igual que una fila en un trámite: todos saben quién va primero.",
   "El orden es: primero lo que está entre paréntesis; después multiplicaciones y divisiones, de izquierda a derecha; al final sumas y restas, de izquierda a derecha. En 3 + 2 × 1,5 se multiplica primero: 2 × 1,5 = 3, y luego 3 + 3 = 6.",
   "Los paréntesis cambian el orden: (3 + 2) × 1,5 = 5 × 1,5 = 7,5. Con fracciones y decimales rige el mismo orden. Para no equivocarte, escribe el resultado de cada paso en una línea nueva y revisa que tenga sentido."],
  [("operatoria combinada", "cuenta que tiene varias operaciones juntas"), ("paréntesis", "signo que agrupa lo que se calcula primero"), ("orden de las operaciones", "regla de qué se calcula primero y qué después"), ("de izquierda a derecha", "orden para operaciones del mismo nivel")],
  [("Multiplicar antes de sumar", "Calcula 3 + 2 × 1,5.", ["Primero la multiplicación: 2 × 1,5 = 3.", "Luego la suma: 3 + 3 = 6."], "6"),
   ("Paréntesis primero", "Calcula (3/4 − 1/4) × 6.", ["Primero el paréntesis: 3/4 − 1/4 = 2/4 = 1/2.", "Luego 1/2 × 6 = 3."], "3")],
  [("Calcular 5 + 2 × 3 como 7 × 3 = 21.", "Se hace de izquierda a derecha sin respetar el orden.", "Se multiplica primero: 2 × 3 = 6 y 5 + 6 = 11."),
   ("Ignorar los paréntesis: 12 − (3 + 4) × 2 como 12 − 3 + 8.", "Se calcula antes de resolver el paréntesis.", "Primero 3 + 4 = 7, luego 7 × 2 = 14 y 12 − 14.")],
  [Q("¿Cuánto es 4 + 2 × 3?", "10", "18", "9", "Se multiplica primero, 2 × 3 = 6, y luego 4 + 6 = 10."),
   Q("¿Cuánto es (4 + 2) × 3?", "18", "10", "12", "El paréntesis va primero: 4 + 2 = 6 y 6 × 3 = 18."),
   Q("¿Cuánto es 10 − 6 ÷ 2?", "7", "2", "8", "Se divide primero, 6 ÷ 2 = 3, y luego 10 − 3 = 7."),
   Q("{F} ¿Cuánto es la cuenta (1)?", "4", "2,75", "5,5", "Primero 3 × 0,5 = 1,5 y luego 2,5 + 1,5 = 4."),
   Q("{F} ¿Cuánto es la cuenta (2)?", "6", "4", "3 1/4", "Primero 1/2 + 1/4 = 3/4 y luego 3/4 × 8 = 6."),
   Q("{F} ¿Cuánto es la cuenta (3)?", "2", "12", "3", "Primero 4 ÷ 0,5 = 8 y luego 10 − 8 = 2."),
   Q("{F} ¿Cuánto es la cuenta (4)?", "3,75", "6,75", "3,5", "Primero 1/2 × 6 = 3 y luego 3 + 0,75 = 3,75."),
   Q("¿Cuánto es 0,5 × 8 − 1,5?", "2,5", "6,5", "5,5", "Primero 0,5 × 8 = 4 y luego 4 − 1,5 = 2,5."),
   Q("¿Cuánto es 1/2 + 1/4 × 2?", "1", "1 1/2", "3/2", "Primero 1/4 × 2 = 1/2 y luego 1/2 + 1/2 = 1."),
   T2("Una persona calcula 5 + 2 × 3 y obtiene 21. ¿Es correcto?", "No: debía multiplicar primero y da 11", "Sí: va de izquierda a derecha", "La multiplicación se resuelve antes que la suma, aunque la suma venga primero."),
   Q("En 12 − (3 + 4) × 1,5, ¿qué operación se hace primero?", "3 + 4", "12 − 3", "4 × 1,5", "Lo que está entre paréntesis siempre se calcula primero."),
   Q("¿Cuánto es (2,5 − 0,5) ÷ 4 + 1/2?", "1", "1 1/2", "2", "Primero 2,5 − 0,5 = 2, luego 2 ÷ 4 = 0,5 y 0,5 + 0,5 = 1."),
   Q("A 20 se le quita el doble de 3,5. ¿Qué cuenta y qué resultado corresponden?", "20 − 2 × 3,5 = 13", "(20 − 2) × 3,5 = 63", "20 × 2 − 3,5 = 36,5", "El doble de 3,5 es 2 × 3,5 = 7, y 20 − 7 = 13.")],
  Q("Un camión de ejemplo lleva 3 cajas de 1,2 kg y 0,4 kg sueltos. ¿Cuántos kilos lleva en total?", "4", "4,8", "1,6", "Primero 3 × 1,2 = 3,6 y luego 3,6 + 0,4 = 4."),
  [("¿Qué se calcula primero en una cuenta con paréntesis?", "Lo que está dentro del paréntesis", "Los paréntesis agrupan lo que debe resolverse primero."),
   ("En Matemática: ¿qué se hace antes, multiplicar o sumar?", "Multiplicar", "La multiplicación va antes que la suma, salvo que haya paréntesis."),
   ("¿Cuánto es 6 − 2 × 1,5?", "3", "2 × 1,5 = 3 y 6 − 3 = 3.")],
  ("Elige dos cuentas de la ficha 2 y resuélvelas escribiendo el resultado de cada paso. Luego inventa una cuenta con paréntesis y otra sin paréntesis que usen los mismos números y da resultados distintos.",
   "(2 + 1) × 1,5 = 4,5 y 2 + 1 × 1,5 = 3,5. Los mismos números dan resultados distintos porque cambia el orden.",
   ["respeta el orden de las operaciones", "escribe cada paso", "muestra el efecto de los paréntesis"],
   ["pasos escritos", "pareja de cuentas"],
   ["resolver de izquierda a derecha sin orden", "ignorar paréntesis"],
   "Si salta pasos, pídele que subraye la operación que hace primero."),
  "Calcula 8 − 2 × 1,5 y (8 − 2) × 1,5.",
  "Pon paréntesis a 1 + 2 × 3 de modo que el resultado sea 9.")

# ============================================================ OAD-04 clase 3
